"""Admin panel HTML. All data comes from authenticated /api/admin routes."""

ADMIN_HTML = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nexus — панель магазина</title>
<style>
:root{color-scheme:dark;--bg:#0b101c;--card:#172235;--line:#304057;--text:#edf3fd;--muted:#9aabc4;--blue:#accdff}*{box-sizing:border-box}html{font-family:Inter,system-ui,sans-serif}body{margin:0;min-height:100vh;background:radial-gradient(circle at 95% 0%,#263c5b 0,transparent 32%),var(--bg);color:var(--text);font-size:14px}button,input,textarea,select{font:inherit}[hidden]{display:none!important}h1,h2,p{margin-top:0}h1{font-size:clamp(26px,3vw,38px);letter-spacing:-.04em}h2{font-size:22px}.muted,small{color:var(--muted)}.login{display:grid;place-items:center;min-height:100vh;padding:20px}.login-card{width:min(430px,100%);padding:36px;border:1px solid var(--line);border-radius:23px;background:linear-gradient(145deg,#1d2b40,#121c2e);box-shadow:0 35px 80px #0007}.logo{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:800}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:linear-gradient(130deg,#f2f7ff,#83a8db);color:#1b2b42;font-size:25px}.login-card .logo{margin-bottom:30px}.login-card p{color:var(--muted)}.layout{display:grid;grid-template-columns:235px minmax(0,1fr);min-height:100vh}.side{position:sticky;top:0;display:flex;flex-direction:column;height:100vh;padding:24px 13px;border-right:1px solid var(--line);background:#101929}.side .logo{margin:0 12px 31px}.nav-label{margin:0 13px 12px;color:#7f93af;font-size:10px;font-weight:800;letter-spacing:.17em}.side nav{display:grid;gap:5px}.side nav button{display:flex;gap:14px;align-items:center;width:100%;padding:13px;border:1px solid transparent;border-radius:11px;background:transparent;color:var(--muted);text-align:left;cursor:pointer}.side nav button span{font-size:18px}.side nav button.active,.side nav button:hover{border-color:#435570;background:#263750;color:#fff}.side-footer{margin-top:auto;padding:18px 12px 0;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.side-footer button{display:block;margin-top:12px;border:0;background:none;color:var(--text);cursor:pointer}.main{width:100%;max-width:1450px;margin:0 auto;padding:38px clamp(18px,3vw,45px) 70px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.eyebrow{color:var(--blue);font-size:10px;font-weight:800;letter-spacing:.2em}.badge{padding:8px 12px;border:1px solid #456182;border-radius:30px;background:#20344b;color:#c7e0ff;font-size:11px}.view{display:none}.view.active{display:block}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:20px}.metric,.panel{border:1px solid var(--line);border-radius:17px;background:linear-gradient(145deg,#1b2a3e,#141e2f);box-shadow:0 15px 30px #0002}.metric{min-height:136px;padding:21px}.metric i{display:grid;place-items:center;width:32px;height:32px;margin-bottom:13px;border-radius:9px;background:#2e4563;color:#b8d5ff;font-style:normal}.metric small{display:block;font-size:11px}.metric strong{display:block;margin-top:6px;font-size:clamp(19px,2vw,27px);letter-spacing:-.04em}.panel{overflow:hidden}.panel-title{padding:20px 22px;border-bottom:1px solid var(--line)}.panel-title h2{margin-bottom:4px}.panel-title p{margin:0;color:var(--muted);font-size:12px}.bar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:19px}.bar h2{margin-bottom:4px}.bar p{margin:0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{padding:16px 20px;border-bottom:1px solid #2a3950;text-align:left}th{color:#8ea1bc;font-size:10px;letter-spacing:.12em;text-transform:uppercase}td{font-size:12px}tbody tr:last-child td{border-bottom:0}td small{display:block;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{text-align:right}.actions button{margin-left:5px}.empty{padding:45px;text-align:center;color:var(--muted)}.pill{display:inline-block;padding:5px 9px;border:1px solid #466e62;border-radius:30px;background:#203b37;color:#a0dfbe;font-size:10px}.pill.off{border-color:#73515a;background:#422d38;color:#ffc0c8}button.primary,button.secondary,button.danger{padding:10px 13px;border:1px solid #a8caff;border-radius:9px;background:linear-gradient(135deg,#edf4ff,#93b7ea);color:#182942;font-size:12px;font-weight:800;cursor:pointer;white-space:nowrap}button.secondary{border-color:#465a76;background:#293c56;color:#e6efff}button.danger{border-color:#845360;background:#542f3d;color:#ffc6ce}.form{display:grid;gap:15px}label{display:grid;gap:7px;color:#bdcae0;font-size:12px;font-weight:700}input,textarea,select{width:100%;padding:11px;border:1px solid #455771;border-radius:9px;outline:none;background:#0e1929;color:var(--text)}input:focus,textarea:focus,select:focus{border-color:#9cbff5;box-shadow:0 0 0 3px #719bd133}textarea{min-height:120px;resize:vertical}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:8px}.search{display:flex;gap:7px}.search input{width:200px}.modal{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:16px;background:#030811cc}.modal-card{position:relative;width:min(650px,100%);max-height:94vh;overflow:auto;padding:27px;border:1px solid #40536d;border-radius:18px;background:#1b293c;box-shadow:0 35px 90px #000a}.modal-card h2{padding-right:28px}.close{position:absolute;top:15px;right:17px;border:0;background:transparent;color:var(--muted);font-size:27px;cursor:pointer}.stock-list{display:grid;gap:8px;max-height:300px;overflow:auto}.stock-line{display:flex;gap:6px}.stock-line input{flex:1}.hint{color:var(--muted);font-size:12px;line-height:1.5}.notice{position:fixed;z-index:30;right:20px;bottom:20px;padding:13px 16px;border:1px solid #577963;border-radius:11px;background:#1e3e32;color:#d4f7df;box-shadow:0 10px 30px #0009}.notice.bad{border-color:#8e5362;background:#4c303b;color:#ffced4}.error{min-height:17px;color:#ff9ba9!important}
@media(max-width:1050px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.layout{display:block}.side{position:relative;height:auto;padding:12px}.side .logo{margin:0 4px 13px}.nav-label,.side-footer{display:none}.side nav{display:flex;overflow:auto}.side nav button{width:auto;flex:none;padding:9px 10px;font-size:11px}.main{padding:24px 13px}.badge{display:none}.bar{align-items:flex-start}.bar .primary{font-size:11px}.search{flex-direction:column}.search input{width:155px}th,td{padding:12px}.modal-card{padding:22px}.form-row{grid-template-columns:1fr}}@media(max-width:400px){.metric{padding:13px;min-height:120px}.metric strong{font-size:18px}}
</style></head><body>
<section id="login" class="login"><div class="login-card"><div class="logo"><span class="mark">✦</span>Nexus Admin</div><h1>Управление магазином</h1><p>Введите секретный ключ администратора</p><form id="loginForm" class="form"><label>Секретный ключ<input id="secret" type="password" autocomplete="current-password" required></label><button class="primary">Войти в панель →</button><p id="loginError" class="error"></p></form></div></section>
<div id="app" class="layout" hidden><aside class="side"><div class="logo"><span class="mark">✦</span>Nexus Admin</div><p class="nav-label">РАЗДЕЛЫ</p><nav><button data-view="dashboard" class="active"><span>▦</span>Обзор</button><button data-view="products"><span>◈</span>Товары</button><button data-view="categories"><span>▤</span>Категории</button><button data-view="customers"><span>♙</span>Покупатели</button><button data-view="orders"><span>≡</span>Покупки</button></nav><div class="side-footer">● Магазин подключён<button id="logout">Выйти</button></div></aside><main class="main"><header class="top"><div><p class="eyebrow">NEXUS STORE / ADMIN</p><h1 id="pageTitle">Обзор магазина</h1><small id="pageSubtitle">Продажи, посещения и популярные категории</small></div><span class="badge">● Панель управления</span></header>
<section id="dashboard" class="view active"><div id="metrics" class="metrics"></div><div class="panel"><div class="panel-title"><h2>Топ категорий</h2><p>Рейтинг по выручке от оплаченных заказов</p></div><div class="table-wrap"><table><thead><tr><th>Место</th><th>Категория</th><th>Продаж</th><th>Выручка</th></tr></thead><tbody id="tops"></tbody></table></div></div></section>
<section id="products" class="view"><div class="bar"><div><h2>Товары</h2><p class="muted">Предложения внутри категорий</p></div><button id="addProduct" class="primary">+ Добавить товар</button></div><div class="panel table-wrap"><table><thead><tr><th>Название</th><th>Категория</th><th>Цена</th><th>Автовыдача</th><th>Статус</th><th></th></tr></thead><tbody id="productRows"></tbody></table></div></section>
<section id="categories" class="view"><div class="bar"><div><h2>Категории</h2><p class="muted">Разделы каталога для покупателей</p></div><button id="addCategory" class="primary">+ Добавить категорию</button></div><div class="panel table-wrap"><table><thead><tr><th>Название</th><th>Порядок</th><th>Статус</th><th></th></tr></thead><tbody id="categoryRows"></tbody></table></div></section>
<section id="customers" class="view"><div class="bar"><div><h2>Покупатели</h2><p class="muted">Клиенты Telegram-бота</p></div><div class="search"><input id="customerSearch" placeholder="Поиск по username"><button id="searchCustomers" class="secondary">Найти</button></div></div><div class="panel table-wrap"><table><thead><tr><th>Username</th><th>Покупатель</th><th>Баланс</th><th>Покупок</th><th></th></tr></thead><tbody id="customerRows"></tbody></table></div></section>
<section id="orders" class="view"><div class="bar"><div><h2>Покупки</h2><p class="muted">История заказов магазина</p></div></div><div class="panel table-wrap"><table><thead><tr><th>Дата</th><th>Покупатель</th><th>Товар</th><th>Сумма</th><th>Статус</th></tr></thead><tbody id="orderRows"></tbody></table></div></section>
</main></div><div id="modal" class="modal" hidden><div class="modal-card"><button id="closeModal" class="close" aria-label="Закрыть">×</button><div id="modalContent"></div></div></div><div id="notice" class="notice" hidden></div><script src="/admin.js" defer></script></body></html>'''
